"""Summarize mailtodo letters without modifying the input tree."""
import argparse
from datetime import datetime
import json
from pathlib import Path
import re


RESOLVED = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}
REQUIRED = ("id", "from", "to", "status", "at")


def read_letter(path, now):
    try:
        lines = path.read_text(encoding="utf-8").split("\n")
    except (OSError, UnicodeError):
        return None, "no_frontmatter"
    if lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if any(not fields.get(key) for key in REQUIRED):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    match = re.match(r"^([0-9]{8}T[0-9]{4})[-_]", path.name)
    if match is None:
        return None, "bad_name"
    try:
        stamp = datetime.strptime(match.group(1), "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    if stamp.strftime("%Y%m%dT%H%M") != match.group(1):
        return None, "bad_name"
    return {"id": fields["id"], "from": fields["from"], "to": fields["to"],
            "status": fields["status"], "re": fields.get("re", ""), "at": at}, None


def letters_in(directory):
    if directory.is_symlink() or not directory.is_dir():
        return []
    return [path for path in directory.iterdir()
            if not path.name.startswith(".") and path.suffix == ".md"
            and not path.is_symlink() and path.is_file()]


def summarize(root, now):
    boxes = {}
    paths = []
    for box in root.iterdir():
        if box.name.startswith(".") or box.is_symlink() or not box.is_dir():
            continue
        inbox = box / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[box.name] = {"inbox": {}, "done": 0}
        paths.extend((path, box.name, "inbox") for path in letters_in(inbox))
        paths.extend((path, box.name, "done") for path in letters_in(inbox / "done"))
    bad = []
    valid = []
    seen = set()
    for path, box, where in sorted(paths, key=lambda item: item[0].relative_to(root).as_posix()):
        relative = path.relative_to(root).as_posix()
        letter, why = read_letter(path, now)
        if why is None and letter["id"] in seen:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        seen.add(letter["id"])
        valid.append((letter, box, where))
        if where == "done":
            boxes[box]["done"] += 1
        else:
            counts = boxes[box]["inbox"]
            status = letter["status"]
            counts[status] = counts.get(status, 0) + 1
    replies = {letter["re"] for letter, _, _ in valid
               if letter["re"] and letter["status"] in RESOLVED}
    opened = [{"id": letter["id"], "from": letter["from"], "to": letter["to"],
               "where": where, "age_min": (now - letter["at"]).total_seconds() // 60}
              for letter, _, where in valid
              if letter["status"] == "REQUEST" and letter["id"] not in replies]
    for item in opened:
        item["age_min"] = int(item["age_min"])
    return {"v": 1, "open": sorted(opened, key=lambda item: (item["to"], item["id"])),
            "boxes": {name: boxes[name] for name in sorted(boxes)},
            "bad": sorted(bad, key=lambda item: (item["file"], item["why"]))}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Summarize mailtodo letters (read-only)")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None or now.utcoffset() is None:
        parser.error("--now must include a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
